import React from 'react';
import './SupportTeam.css'; // Make sure to move the CSS here too
import './About.css';

const SupportTeam = () => {
    return (
        <div className="about-departments">
            <h1 className="section-title">Our Departments</h1>
            <div className="infinity-responsive-grid">
                {/* ... all your department cards go here ... */}
                <div className="department-card">
                    <h2>
                        <img src="https://cdn-icons-png.flaticon.com/512/906/906175.png" alt="IT Logo" /> 
                        IT Department
                    </h2>
                    <div className="member">
                        <strong>Prabin Kafle</strong><br />
                        Contact: 078-503301 Ext-109<br />
                        Email: prabin.kafle@infinitylbsl.com.np
                    </div>
                    {/* Repeat for other members/departments */}
                </div>
            </div>
        </div>
    );
};

export default SupportTeam;
